   "text": "Araç giydirmede iki ana folyo türü vardır. Döküm folyo ince ve esnektir, eğimli yüzeylere iyi oturur, genellikle daha uzun ömürlüdür ve tam kaplamada tercih edilir. Kalenderlenmiş folyo daha ekonomiktir ve düz yüzeylerde kısa-orta vadeli işler için uygundur. Ömrü, laminasyon ve doğru bakım belirler."
