   "section": "Uygulama sonrası bakım",
   "text": "İyi uygulanmış bir folyonun ömrü bakım alışkanlıklarıyla doğrudan ilişkilidir. Aşağıdaki noktalar genel öneriler olup folyo üreticisinin bakım tavsiyesi her zaman önceliklidir. İlk günlerde yıkamadan kaçının. Yapıştırıcının yüzeye tutunması için uygulayıcının önerdiği bekleme süresine uyun. Yıkamayı nazik yapın. Yumuşak sünger veya mikrofiber bez ve nötr deterjan kullanın. Basınçlı yıkamada mesafe ve basınç için folyo üreticisinin önerisine uyun; kenarlara ve birleşim yerlerine doğrudan sıkmayın. Aşındırıcı ürünlerden uzak durun. Sert çözücüler, fırçalı otomatik yıkama sistemleri ve kaba pastalar yüzeyi ve laminasyonu bozabilir. Gölgede park edin. Uzun süreli doğrudan güneş, solma ve yaşlanmayı hızlandırır. Kenarları izleyin. Kalkma belirtisi görürseniz kendiniz çekmeyin; kısa sürede uygulayıcıya gösterin."
