   "text": "Doğru folyoyu seçmek için önce aracın ve işin koşullarını netleştirmek gerekir. Aşağıdaki sorular, keşif görüşmesinde de yol gösterir. Yüzey düz mü, kavisli mi? Derin kavisli yüzeylerde döküm folyo çoğunlukla daha güvenli bir seçimdir. Uygulama ne kadar süre kalacak? Kısa süreli kampanyada ekonomik seçenek yeterli olabilir; uzun süreli kurumsal giydirmede ömür ön plana çıkar. Araç günlük ve yoğun mu kullanılıyor? Sık yıkanan ve günde çok yol yapan filo araçlarında laminasyon ve doğru malzeme seçimi daha kritik hale gelir. Kaplama sonrası sökülecek mi? Araç satılacak veya görsel değişecekse, sökülebilirlik ve boya yüzeyine etkisi de düşünülmelidir. Bu konuda folyo üreticisinin bilgisi esas alınır. Boya durumu nasıl? Kaplama, sağlam bir boya yüzeyi üzerinde sağlıklı tutunur. Boyası bozuk, çatlamış yüzeyler kaplama öncesi değerlendirilmelidir."
