   "text": "Eczane tabelaları diğer işyeri tabelalarından farklı olarak meslek mevzuatına da tabidir. Temel düzenleme, 12 Nisan 2014 tarihli ve 28970 sayılı Resmî Gazete'de yayımlanan Eczacılar ve Eczaneler Hakkında Yönetmelik'tir. Yönetmeliğin metnine Resmî Gazete arşivinden ulaşabilirsiniz. Yönetmelik sonradan değişikliğe uğramış olabilir. Bu nedenle tabela üretimine başlamadan önce güncel ve birleştirilmiş metni kontrol etmenizi öneririz. Standartların kendisi ise Türk Eczacıları Birliği tarafından belirlenir; birliğin sayfasına teb.org.tr adresinden ulaşılır."
