   "text": "Yönetmeliğe uygun olmak, belediye iznini gereksiz kılmaz. Eczane tabelası da diğer işyeri tabelaları gibi ilgili belediyenin ilan ve reklam düzenlemelerine ve ilan ve reklam vergisine tabidir. İstanbul'da bu süreç ilçe belediyesi üzerinden yürür. Adımlar için İstanbul'da tabela izni nasıl alınır yazımızı okuyabilirsiniz."
