   "text": "Eczane, vitrini ve girişiyle bir bütün olarak algılanır. Levha standarda uygun olsa bile giriş kapısı, cam üzerindeki bilgilendirme ve iç mekân yönlendirmesi tutarlı tasarlanırsa eczane daha profesyonel görünür. Cam yüzeyler için cam kaplama , iç mekân için iç mekân tabelaları uygulamalarımız var. Standart levhanın dışında kalan alanlarda tasarım serbestliği daha geniştir; ancak eczane kimliğini bozacak, yanıltıcı veya standart levhayla karışacak uygulamalardan kaçınmak gerekir. Şüpheye düştüğünüz her noktada Türk Eczacıları Birliği veya bağlı olduğunuz eczacı odasına danışın."
