   "text": "Kutu harf, içi boş ve LED yerleştirilmiş üç boyutlu bir gövdedir; pleksi harf ise pleksiglas plakadan kesilen daha ince ve ekonomik bir harftir. Prestij, dayanıklılık ve gece görünürlüğü öncelikliyse kutu harf; bütçe ve hızlı çözüm öncelikliyse pleksi harf genellikle daha uygun bir seçimdir."
