   "section": "Pleksi harf nedir?",
   "text": "Pleksi harf, pleksiglas plakadan kesilerek hazırlanan, genellikle daha ince yapıdaki harftir. Renkli veya şeffaf pleksi kullanılabilir. Arkadan aydınlatma ile uygulandığında duvara yansıyan yumuşak bir ışık halkası (halo etkisi) oluşturur ve zarif bir görünüm sağlar. Arkadan aydınlatmalı seçenekler için LED harf sayfasına göz atabilirsiniz. Pleksi harfin güçlü yanları Genellikle daha ekonomik ve hızlı bir çözümdür. İnce ve hafif yapısı montajı kolaylaştırır. Renk ve şekil seçeneği geniştir. Pleksi harfin dikkat edilecek yanları Pleksiglas yüzeyler çizilmeye ve uzun süreli güneş etkisine karşı kutu harf kadar dayanıklı olmayabilir. Malzeme kalitesi ve UV dayanımı bu noktada belirleyicidir. Ayrıca ışık dağılımı, kutu harfteki kadar homojen olmayabilir."
