   "text": "Cam uygulamalarında iki temel seçenek öne çıkar. One way vision (tek yönlü görüş) folyo, delikli yapısı sayesinde içeriden dışarıyı görmeye izin verirken dışarıdan tam kaplı bir görsel sunar. Kumlama (dumanlı, buzlu) folyo ise camı buzlu cam görünümüne getirerek mahremiyet ve şık bir doku sağlar. Bunların yanında renkli veya baskılı şeffaf folyolar, kesim yazı ve logolar ile şerit ve desenler de uygulanır. Baskılı uygulamalarda folyonun üzerine koruyucu laminasyon çekilebilir. Dayanım, üretici verisine ve ortam koşullarına göre değişir."
