   "text": "Keşif ve ölçü: filodaki araç modellerini görür, yüzeyleri ölçeriz. Tasarım onayı: her modele uyarlanmış şablonu birlikte onaylarız. Baskı ve laminasyon: tüm araçların baskısı aynı ayarlarla üretilir. Uygulama: araçlar atölyemizde sırayla kaplanır."
